data class DocState(val text: String, val caret: Int)   // immutable memento

class Editor {
    var state = DocState("", 0)
        private set
    private val history = ArrayDeque<DocState>()          // caretaker
    fun save() {
        history.addLast(state)
        if (history.size > 100) history.removeFirst()
    }
    fun undo() { state = history.removeLastOrNull() ?: state }
}

